package com.ptraam.tracker;

import android.Manifest;import android.app.*;import android.content.*;import android.location.*;import android.os.*;import android.widget.*;import org.json.JSONObject;import java.text.*;import java.util.*;import java.util.concurrent.*;

public final class AttendanceActivity extends Activity {
 private final ExecutorService worker=Executors.newSingleThreadExecutor();private TextView status,message;private Button in,out;private boolean busy;private LocationListener listener;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(!Session.valid(this)){login();return;}setContentView(R.layout.activity_attendance);status=findViewById(R.id.attendance_status);message=findViewById(R.id.attendance_message);in=findViewById(R.id.attendance_check_in);out=findViewById(R.id.attendance_check_out);in.setOnClickListener(v->capture("checkIn"));out.setOnClickListener(v->capture("checkOut"));findViewById(R.id.attendance_back).setOnClickListener(v->finish());load();}
 private void load(){request("/workforce/state",new JSONObject(),false);}
 private void capture(String action){if(busy)return;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=android.content.pm.PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{Manifest.permission.ACCESS_COARSE_LOCATION,Manifest.permission.ACCESS_FINE_LOCATION},20);return;}LocationManager gps=getSystemService(LocationManager.class);if(!gps.isProviderEnabled(LocationManager.GPS_PROVIDER)){show("Turn on device location before recording attendance.");return;}busy=true;buttons();message.setText("Waiting for an accurate GPS fix…");listener=new LocationListener(){public void onLocationChanged(Location l){long age=SystemClock.elapsedRealtimeNanos()-l.getElapsedRealtimeNanos();if(!l.hasAccuracy()||l.getAccuracy()<=0||l.getAccuracy()>100||age<0||age>30000000000L||l.isFromMockProvider())return;gps.removeUpdates(this);listener=null;try{request("/attendance",new JSONObject().put("action",action).put("fix",new JSONObject().put("lat",l.getLatitude()).put("lng",l.getLongitude()).put("accuracy",l.getAccuracy()).put("time",l.getTime())),true);}catch(Exception e){show("Unable to read location.");}}public void onProviderDisabled(String p){show("Device location was disabled.");}public void onProviderEnabled(String p){}@SuppressWarnings("deprecation")public void onStatusChanged(String p,int s,Bundle e){}};try{gps.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,0,listener,Looper.getMainLooper());}catch(SecurityException e){show("Location permission is required.");}}
 private void request(String path,JSONObject body,boolean submitted){busy=true;buttons();worker.execute(()->{try{JSONObject r=Api.post(this,path,body,true);runOnUiThread(()->{busy=false;buttons();JSONObject a=r.optJSONObject("attendance");if(a!=null){String text=a.optString("status","Not Checked In");if(a.optLong("checkIn",0)>0)text+="\nCheck in: "+time(a.optLong("checkIn"));if(a.optLong("checkOut",0)>0)text+="\nCheck out: "+time(a.optLong("checkOut"));status.setText(text);}message.setText(submitted?"Attendance updated.":"");});}catch(Exception e){runOnUiThread(()->show(e.getMessage()));}});}
 private String time(long value){return new SimpleDateFormat("h:mm a",Locale.getDefault()).format(new Date(value));}private void buttons(){in.setEnabled(!busy);out.setEnabled(!busy);}private void show(String text){busy=false;buttons();message.setText(text==null?"Unable to update attendance.":text);}private void login(){startActivity(new Intent(this,LoginActivity.class));finish();}@Override public void onDestroy(){if(listener!=null)try{getSystemService(LocationManager.class).removeUpdates(listener);}catch(Exception ignored){}worker.shutdownNow();super.onDestroy();}
}
